(() => {
'use strict';
const $ = (s, root = document) => root.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {
 mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',
 post:'<path d="M4 8h16M5 8V5h14v3M6 8v13h12V8M9 12h6M9 16h6M3 21h18"/><path d="M10 3h4"/>',
 globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c6 6 6 12 0 18-6-6-6-12 0-18Z"/>',
 chat:'<path d="M21 11.5a8.5 8.5 0 0 1-8.5 8.5H4l-2 2V11.5a9.5 9.5 0 1 1 19 0Z"/><path d="M7 9h9M7 13h6"/>',
 collection:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M7 5V3h10v2M7 10h10M7 14h6"/>',
 pin:'<path d="M19 9c0 5-7 12-7 12S5 14 5 9a7 7 0 1 1 14 0Z"/><circle cx="12" cy="9" r="2.5"/>',
 arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',
 chevron:'<path d="m9 5 7 7-7 7"/>',
 down:'<path d="m6 9 6 6 6-6"/>',
 back:'<path d="m14 5-7 7 7 7M7 12h14"/>',
 close:'<path d="m6 6 12 12M18 6 6 18"/>',
 bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',
 heart:'<path d="M20.5 4.5c-2.2-2.2-6-1.7-8.5 1.3-2.5-3-6.3-3.5-8.5-1.3S1.7 10.8 5 14l7 7 7-7c3.3-3.2 3.7-7.3 1.5-9.5Z"/>',
 stamp:'<path d="M4 3h16v3l-1 1 1 1v3l-1 1 1 1v3l-1 1 1 1v3H4v-3l1-1-1-1v-3l1-1-1-1V8l1-1-1-1V3Z"/><rect x="8" y="7" width="8" height="10" rx="1"/>',
 plane:'<path d="m22 2-7 20-4-9-9-4 20-7ZM11 13 22 2"/>',
 lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',
 check:'<path d="m5 12 4 4L20 5"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',
 search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
 pen:'<path d="m15 4 5 5M4 20l5-1L21 7a2 2 0 0 0-5-5L4 14v6Z"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',
 spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z"/>',
 upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6"/>',
 image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="1.5"/><path d="m3 18 6-7 5 5 3-3 4 5"/>',
 settings:'<path d="m9 3-.6 2.5L6 7 3.5 6.5 2 9l2 2v2l-2 2 1.5 2.5L6 17l2.4 1.5L9 21h6l.6-2.5L18 17l2.5.5L22 15l-2-2v-2l2-2-1.5-2.5L18 7l-2.4-1.5L15 3H9Z"/><circle cx="12" cy="12" r="3"/>',
 shield:'<path d="m12 2 8 4v6c0 6-8 10-8 10S4 18 4 12V6l8-4Z"/><path d="m8 12 3 3 5-6"/>',
 wallet:'<path d="M20 7V4H5a2 2 0 0 0 0 4h16v12H5a2 2 0 0 1-2-2V6M21 12h-5v4h5M17 14h.01"/>',
 logout:'<path d="M9 4H4v16h5M9 12h12m-4-4 4 4-4 4"/>',
 flag:'<path d="M5 21V3c4-4 10 4 14 0v11c-4 4-10-4-14 0"/>'
};
const icon = n => `<svg viewBox="0 0 24 24" aria-hidden="true">${paths[n] || paths.mail}</svg>`;
const city = id => PP.cities[id] || PP.cities.tokyo;
const fmt = n => Number(n).toLocaleString('zh-CN', {maximumFractionDigits:2});
const date = s => new Date(s).toLocaleDateString('zh-CN',{month:'long',day:'numeric'});
const statusText = {unused:'未使用',listed:'上架中',used:'已使用',sent:'已寄出',received:'已签收',delivered:'已投递',transit:'旅途中',pending:'待审核',approved:'已通过'};
const badge = s => `<span class="status ${esc(s)}">${statusText[s] || esc(s)}</span>`;
const storage = {get(k,f){try{return JSON.parse(localStorage.getItem(k)) ?? f;}catch{return f;}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v));}catch{toast('浏览器存储已满，未保存此项设置');}}};
let view = ['postoffice','messages','market','profile','creator'].includes(location.hash.slice(1)) ? location.hash.slice(1) : 'postoffice';
let filter='all', marketType='all', marketCity='all', marketSort='new', marketSearch='', messageTab='letters', profileType='cards', assetTab='unused';
let favorites=storage.get('posterposta-favorites',[]), compose=null, creationImage='', afterLogin=null, activeModal=null, toastTimer=null, lastFocus=null;
let modalStack=[];
const main=$('#main');

function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3300);}
function error(e){const el=$('#form-error');if(el){el.textContent=e.message || String(e);el.classList.add('show');el.scrollIntoView({block:'nearest',behavior:'smooth'});}else toast(e.message || String(e));}
function empty(title,sub,action='nav',id='postoffice',label='去当地邮局逛逛'){return `<div class="empty">${icon('mail')}<h3>${title}</h3><p>${sub}</p><button class="secondary" data-action="${action}" data-id="${id}">${label} ${icon('arrow')}</button></div>`;}
function seal(id){return `<div class="postal-seal"><span>POSTERPOSTA</span><strong>${city(id).en}</strong><small>MEMORIES · DELIVERED</small></div>`;}
function stamp(p){return `<div class="stamp-mini"><img src="${esc(p.img)}" alt="${esc(p.title)}"><small>${city(p.city).en} · POSTA</small></div>`;}
function citySelect(name,value,blank=false){return `<select name="${name}" id="${name}" required>${blank?'<option value="">选择收信城市</option>':''}${Object.entries(PP.cities).map(([id,c])=>`<option value="${id}" ${id===value?'selected':''}>${c.name} · ${c.country}</option>`).join('')}</select>`;}
function heading(en,title,sub,right=''){return `<div class="page-heading"><div><div class="eyebrow">${en}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${right}</div>`;}
function syncChrome(){
 const nav=[['postoffice','post','当地邮局'],['messages','chat','来往信件'],['market','globe','世界市集'],['profile','collection','我的收藏']];
 const html=nav.map(([id,ic,label])=>`<button class="nav-item ${view===id||(view==='creator'&&id==='profile')?'active':''}" data-action="nav" data-id="${id}" ${view===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span>${id==='messages'?`<span class="nav-count">${PP.state.letters.length}</span>`:''}</button>`).join('');
 $('#desktop-nav').innerHTML=html;$('#mobile-nav').innerHTML=html;
 $('#brand-icon').innerHTML=icon('mail');$('#sidebar-sketch').innerHTML='<svg viewBox="0 0 100 70"><rect x="12" y="14" width="67" height="43" rx="2"/><path d="m12 15 34 27 33-27M12 57l25-24M79 57 55 34M73 5l16-3-5 13M79 11 90 0M5 26l-4 2M5 36H0"/><rect x="63" y="19" width="11" height="13" stroke-dasharray="1.5 1.5"/><path d="m66 27 3-5 3 5"/></svg>';
 $('#location-pill').innerHTML=`${icon('pin')}<span>${city(PP.state.location).name}，${city(PP.state.location).country}</span><span class="mini-demo">演示</span>${icon('down')}`;
 $('#notification-icon').innerHTML=icon('bell');
 const u=PP.state.user;$('#top-avatar').textContent=u?Array.from(u.name)[0]:'P';
 $('#user-entry').innerHTML=`<span class="avatar">${u?esc(Array.from(u.name)[0]):'P'}</span><span><strong>${u?esc(u.name):'你好，旅行者'}</strong><small>${u?'你的私人小邮局':'用邮箱开启旅程'}</small></span>`;
 $('#breadcrumb').textContent=({postoffice:'当地邮局',messages:'来往信件',market:'世界市集',profile:'我的收藏',creator:'创作中心'})[view];
}
function render(){syncChrome();main.innerHTML=({postoffice:home,messages:messages,market:market,profile:profile,creator:creator})[view]();main.style.animation='none';void main.offsetWidth;main.style.animation='';}
function navigate(id){closeModal(true);view=id;history.replaceState(null,'','#'+id);render();window.scrollTo({top:0,behavior:'smooth'});}
function cardTile(p,opts={}){
 const m=opts.market, asset=opts.asset;const action=asset?'asset-detail':'detail';const target=asset?asset.id:p.id;
 let media=p.type==='stamp'?`<div class="stamp-large"><img src="${esc(p.img)}" alt="${esc(p.title)}"><span>${city(p.city).en}<b>${fmt(p.price)}</b></span></div>`:`<img src="${esc(p.img)}" alt="${esc(p.title)}" loading="lazy"><span class="card-tag">${esc(m?city(p.city).name:p.tag)}</span><span class="card-bottom-label">${city(p.city).en} ${p.id.includes('sakura')?'IN BLOOM':'MOMENTS'}</span>`;
 let actions='';
 if(asset){
  if(asset.status==='unused')actions=`<div class="asset-actions"><button data-action="${p.type==='card'?'compose':'use-stamp'}" data-id="${asset.id}">${p.type==='card'?'写张明信片':'挑一张卡片'}</button><button class="secondary-action" data-action="list-asset" data-id="${asset.id}">转售</button></div>`;
  if(asset.status==='listed'){const offer=PP.state.market.find(m=>m.assetId===asset.id&&m.active);actions=`<div class="asset-actions"><button data-action="unlist" data-id="${offer?.id || ''}">下架，放回收藏</button></div>`;}
 }
 return `<article class="postcard ${p.type==='stamp'?'stamp-product':''}"><button class="postcard-art" data-action="${action}" data-id="${target}" ${m?`data-market="${m.id}"`:''} aria-label="查看${esc(p.title)}">${media}</button>${!asset?`<button class="like-btn ${favorites.includes(p.id)?'liked':''}" data-action="favorite" data-id="${p.id}" aria-label="${favorites.includes(p.id)?'取消喜欢':'喜欢'}${esc(p.title)}" aria-pressed="${favorites.includes(p.id)}">${icon('heart')}</button>`:''}<div class="card-info"><div><h3>${esc(p.title)}</h3><p class="card-meta">${icon('pin')}${city(p.city).name}<span>·</span>${esc(p.creator)}</p></div>${asset?badge(asset.status):`<span class="card-price ${!m&&!p.price?'free':''}">${!m&&!p.price?'免费':`<span class="price-unit">¥</span>${fmt(m?m.price:p.price)}`}</span>`}</div>${m?`<div class="seller-line"><span class="avatar ${m.seller==='小满'?'peach':''}">${esc(m.sellerInitial)}</span>${esc(m.seller)}<button class="text-link" data-action="${m.own?'unlist':'consult'}" data-id="${m.id}">${m.own?'下架作品':'聊一聊'} ↗</button></div>`:''}${actions}</article>`;
}
function home(){
 const c=city(PP.state.location),free=PP.cityProducts().find(p=>p.price===0),all=PP.cityProducts().filter(p=>p.price>0);
 let cards=filter==='stamps'?PP.cityProducts('stamp'):filter==='favorites'?PP.cityProducts().filter(p=>favorites.includes(p.id)):filter==='nature'?all.filter(p=>/sakura|temple/.test(p.id)):filter==='night'?all.filter(p=>/tower|night|rain/.test(p.id)):all;
 const dateNow=new Date();const dateEN=dateNow.toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}).toUpperCase();
 const claimed=PP.state.claimedFree;
 return heading('YOUR LOCAL POST OFFICE',`把${c.name}，寄给某个人。`,'只有亲自路过的风景，才有属于你的故事。',`<div class="date-note">${dateEN}<span>A GOOD DAY TO SEND A LITTLE LOVE</span></div>`)+
 `<section class="hero"><div class="hero-copy"><div class="hero-topline"><span class="dot"></span>${claimed?'把旅途留在一张卡片里':'旅行的第一张，送给你'}</div><h2>${PP.state.location==='tokyo'?'把东京的晚风，<br>寄给你。':`来自${c.name}的此刻，<br>见字如面。`}</h2><p class="hero-desc">${PP.state.location==='tokyo'?'走过街角的便利店，听见远处的电车。<br>这一刻，我想起了你。':'在陌生的街角停一停，把眼前的风景，<br>交给一封慢慢抵达的信。'}</p><button class="primary" data-action="${claimed?'my-free':'claim'}" data-id="${free.id}">${claimed?'去写一张明信片':'免费领取，写下此刻'} ${icon('arrow')}</button><p class="hero-smallprint">${claimed?'免费礼已领取 · 收藏里的风景正等你提笔':'每个账号首张免费 · 附赠一枚当地邮票 · 无需付费'}</p></div><button class="hero-photo" data-action="detail" data-id="${free.id}" aria-label="查看${c.name}免费明信片"><img src="${free.img}" alt="${c.name}的城市风景"><span class="hero-photo-badge">${c.name}限定 · FIRST POSTCARD</span>${seal(PP.state.location)}<span class="hero-photo-title"><strong>${c.en}</strong><small>A LITTLE PIECE OF NOW</small></span></button><div class="hero-perforation"></div></section>
 <section class="how-strip" aria-label="使用方式"><div class="how-item"><span class="how-icon">${icon('pin')}</span><div><strong>一座城市，一份记忆</strong><p>只在你所在的城市，发现当地明信片</p></div></div><div class="how-item"><span class="how-icon">${icon('pen')}</span><div><strong>一张卡片，一点想念</strong><p>选枚邮票，写给那个想起的人</p></div></div><div class="how-item"><span class="how-icon">${icon('clock')}</span><div><strong>慢慢抵达，刚刚好</strong><p>1–10 个工作日，让期待有点重量</p></div></div></section>
 <div class="section-heading"><div class="section-title"><h2>${c.name}的小小切片</h2><small>COLLECT A MOMENT</small></div><button class="text-link" data-action="location">${icon('pin')} 来自你的当前城市</button></div>
 <div class="filter-row">${[['all','全部风景'],['nature','自然与季节'],['night','城市夜色'],['stamps','当地邮票']].map(([id,label])=>`<button class="chip ${filter===id?'active':''}" data-action="filter" data-id="${id}">${label}</button>`).join('')}<span class="filter-hint">${icon('lock')} 仅限${c.name}领取与购买</span></div>
 <div class="postcard-grid">${cards.length?cards.map(p=>cardTile(p)).join(''):empty('这一页，等待新的风景','这个分类暂时没有作品，换个分类逛逛吧。','filter','all','查看全部风景')}</div>
 <section class="collection-banner">${stamp(PP.product(PP.state.location+'-stamp'))}<div><h3>小小邮票，也装得下大大的世界。</h3><p>收集城市的独特印记，为下一封信挑一枚邮票。</p></div><button class="text-link" data-action="filter" data-id="stamps">去集邮 <span>↗</span></button></section>`;
}
function market(){
 let offers=PP.state.market.filter(m=>m.active).filter(m=>{const p=PP.product(m.productId);return (marketType==='all'||p.type===marketType)&&(marketCity==='all'||p.city===marketCity)&&(!marketSearch||[p.title,p.creator,m.seller,city(p.city).name].some(t=>t.toLowerCase().includes(marketSearch.toLowerCase())));});
 if(marketSort==='low')offers.sort((a,b)=>a.price-b.price);if(marketSort==='high')offers.sort((a,b)=>b.price-a.price);if(marketSort==='new')offers=offers.slice().reverse();
 return heading('THE WORLD, IN LITTLE PIECES','世界很大，风景可以交换。','这里不设距离。收藏一份别人路过的美好，也分享你的。',`<button class="primary" data-action="create">${icon('plus')} 发布创作</button>`)+
 `<div class="market-banner"><div><div class="eyebrow">A PASSPORT TO SOMEWHERE ELSE</div><h2>没有去过，也可以珍藏。</h2><p>全球明信片与邮票自由流转。产地被保留，新的故事由你续写。</p></div>${icon('globe')}</div>
 <div class="market-bar"><div class="filter-row">${[['all','全部作品'],['card','明信片'],['stamp','邮票']].map(([id,label])=>`<button class="chip ${marketType===id?'active':''}" data-action="market-type" data-id="${id}">${label}</button>`).join('')}</div><label class="searchbox">${icon('search')}<input id="market-search" aria-label="搜索市集" placeholder="寻找城市、风景或创作者" value="${esc(marketSearch)}"></label><select class="select-small" id="market-city" aria-label="筛选产地"><option value="all">所有城市</option>${Object.entries(PP.cities).map(([id,c])=>`<option value="${id}" ${marketCity===id?'selected':''}>${c.name}</option>`).join('')}</select><select class="select-small" id="market-sort" aria-label="排序"><option value="new" ${marketSort==='new'?'selected':''}>最近上架</option><option value="low" ${marketSort==='low'?'selected':''}>价格从低到高</option><option value="high" ${marketSort==='high'?'selected':''}>价格从高到低</option></select></div>
 <div class="postcard-grid">${offers.length?offers.map(m=>cardTile(PP.product(m.productId),{market:m})).join(''):empty('还没有遇见这一份风景','换个关键词，或者发布你自己的第一件作品。','clear-market','','重新看看')}</div>
 <div class="notice">${icon('shield')}<span>安心交换：只交易未使用的数字资产，上架即锁定，成交后转移使用权。作品版权仍归创作者所有。当前商品、咨询与交易均为本地演示。</span></div>`;
}
function messages(){
 const letters=PP.state.letters.slice().reverse(),threads=PP.state.community.slice().reverse();
 return heading('LETTERS & LITTLE CONVERSATIONS','让想念，有来有往。','一张明信片是故事的开始，而不是结束。',`<button class="secondary" data-action="choose-card">${icon('pen')} 写一张</button>`)+
 `<div class="tabs"><button class="tab ${messageTab==='letters'?'active':''}" data-action="message-tab" data-id="letters">明信片来往<span class="tab-count">${letters.length}</span></button><button class="tab ${messageTab==='community'?'active':''}" data-action="message-tab" data-id="community">市集交流<span class="tab-count">${threads.length}</span></button></div><p class="inbox-subtitle">${messageTab==='letters'?'旅途中的信件暂不开放聊天；投递完成后，故事可以继续。':'与卖家聊过的作品、在市集留下的话，都收在这里。'} ${!PP.state.user?'当前展示体验信件，登录后可互动。':''}</p>
 <div class="message-layout"><div class="message-list">${messageTab==='letters'?(letters.length?letters.map(l=>{const p=PP.product(l.productId);return `<button class="message-row" data-action="letter" data-id="${l.id}"><img class="message-thumb" src="${p.img}" alt="${esc(p.title)}"><div class="message-body"><div class="message-top"><strong>${city(l.fromCity).name} → ${l.status==='received'?'我':esc(l.toName)}</strong>${badge(l.status)}</div><p>${esc(l.messages.length?l.messages[l.messages.length-1].text:l.message)}</p><small>${l.status==='transit'?`预计 ${date(l.eta)} 抵达 · 聊天待开启`:`${date(l.sentAt)} · ${l.sample?'体验信件':'数字明信片'}`}</small></div></button>`;}).join(''):empty('邮筒里，还很安静','寄出第一张明信片，等一段故事开始。')):threads.map(t=>`<button class="message-row" data-action="thread" data-id="${t.id}"><img class="message-thumb" src="${PP.product(t.productId).img}" alt="${esc(PP.product(t.productId).title)}"><div class="message-body"><div class="message-top"><strong>${esc(t.peer)}</strong><span class="status">${t.marketId?'交易咨询':'社区交流'}</span></div><p>${esc(t.messages.at(-1)?.text || t.title)}</p><small>${esc(t.title)}</small></div></button>`).join('')}</div><aside class="message-aside">${seal(PP.state.location)}<h3>有些话，<br>慢一点也没关系。</h3><p>信件会沿着城市之间的距离，<br>在 1–10 个工作日后抵达。<br>不必催促，风景正在路上。</p><button class="primary" data-action="choose-card">寄出一个新的故事 ${icon('arrow')}</button></aside></div>`;
}
function profile(){
 const u=PP.state.user,assets=PP.ownAssets();
 const visible=profileType==='favorites'?favorites.map(id=>PP.products.find(p=>p.id===id)).filter(Boolean):assets.filter(a=>PP.product(a.productId).type===(profileType==='stamps'?'stamp':'card')&&(profileType==='stamps'?a.status==='unused':a.status===assetTab));
 return `<div class="eyebrow">YOUR PERSONAL POST OFFICE</div><div class="profile-header"><div class="profile-avatar">${u?esc(Array.from(u.name)[0]):'P'}</div><div><h1>${u?esc(u.name):'你好，旅行者。'}</h1><p>${u?esc(u.email):'用一个邮箱，收藏你的整个世界。'}</p>${!u?'<button class="text-link" data-action="login">注册 / 登录 ↗</button>':''}</div><button class="icon-button" data-action="settings" aria-label="设置">${icon('settings')}</button></div>
 <div class="profile-stats"><div class="profile-stat"><strong>${assets.filter(a=>PP.product(a.productId).type==='card'&&['unused','received','listed'].includes(a.status)).length}</strong><span>珍藏的明信片</span></div><div class="profile-stat"><strong>${assets.filter(a=>PP.product(a.productId).type==='stamp'&&a.status==='unused').length}</strong><span>未使用邮票</span></div><div class="profile-stat"><strong>${PP.state.letters.filter(l=>l.status!=='received').length}</strong><span>寄出的心意</span></div><div class="profile-stat"><strong>${new Set(assets.filter(a=>['unused','received','listed'].includes(a.status)).map(a=>PP.product(a.productId).city)).size}</strong><span>收集的城市</span></div></div>
 <div class="tabs">${[['cards','明信片'],['stamps','邮票册'],['favorites','我喜欢的']].map(([id,label])=>`<button class="tab ${profileType===id?'active':''}" data-action="profile-type" data-id="${id}">${label}${id==='favorites'?`<span class="tab-count">${favorites.length}</span>`:''}</button>`).join('')}</div>
 <div class="profile-controls">${profileType==='cards'?`<div class="filter-row">${[['unused','未使用'],['received','已签收'],['listed','上架中'],['sent','已寄出']].map(([id,label])=>`<button class="chip ${assetTab===id?'active':''}" data-action="asset-tab" data-id="${id}">${label}</button>`).join('')}</div>`:`<p class="inbox-subtitle" style="margin:0">${profileType==='stamps'?'邮票册只展示未使用邮票；已贴用的邮票保存在寄信记录里。':'喜欢不代表拥有，点开作品即可查看获取方式。'}</p>`}<button class="tip-button" data-action="rules">${icon('info')} 数字资产规则</button></div>
 <div class="postcard-grid">${visible.length?visible.map(item=>profileType==='favorites'?cardTile(item):cardTile(PP.product(item.productId),{asset:item})).join(''):empty('这一格，留给下一段旅程','去邮局发现风景，或去市集交换一份新的记忆。')}</div>
 <section class="creator-entry">${icon('pen')}<div><h3>每个人，都可以是一座城市的作者。</h3><p>把你的画、照片和灵感，变成有人珍藏的作品。</p></div><button class="text-link" data-action="nav" data-id="creator">创作中心 ↗</button></section>
 <button class="tip-button" data-action="transactions">${icon('wallet')} 查看演示订单与收支</button>${!u?'<p class="layout-note">当前为示例收藏。注册后可体验资产管理，所有数据仅保存在本浏览器。</p>':''}`;
}
function creator(){
 return `<button class="back-button" data-action="nav" data-id="profile">${icon('back')} 返回我的收藏</button>`+heading('THE CREATOR STUDIO','让你的风景，被世界珍藏。','从一张照片、一幅画开始，做一个为城市写信的人。',`<button class="primary" data-action="create">${icon('plus')} 新建作品</button>`)+
 `<div class="creator-stats"><div class="stat-card"><span>累计创作</span><strong>${PP.state.creations.length}</strong><small>每件作品，独立的使用权</small></div><div class="stat-card"><span>在售作品</span><strong>${PP.state.market.filter(m=>m.own&&m.active).length}</strong><small>上架即锁定对应资产</small></div><div class="stat-card"><span>可结算收入</span><strong>¥${fmt(PP.state.revenue)}</strong><small>暂无真实交易与结算</small></div></div>
 <div class="section-heading"><div class="section-title"><h2>我的创作</h2><small>MADE BY YOU</small></div><button class="text-link" data-action="creator-rules">创作与收益说明 ↗</button></div>
 ${PP.state.creations.length?PP.state.creations.slice().reverse().map(w=>{const a=PP.ownAssets().find(a=>a.productId===w.productId);const offer=PP.state.market.find(m=>m.assetId===a?.id&&m.active);return `<article class="creator-work"><img src="${esc(w.img)}" alt="${esc(w.title)}"><div><h3>${esc(w.title)}</h3><p>${city(w.city).name} · ${w.type==='card'?'明信片':'邮票'} · ¥${fmt(w.price)} · ${date(w.createdAt)}</p></div><div class="creation-actions">${badge(w.status==='pending'?'pending':a?.status==='listed'?'listed':'approved')}<button class="secondary" data-action="${w.status==='pending'?'review':offer?'unlist':'asset-detail'}" data-id="${w.status==='pending'?w.id:offer?offer.id:a.id}">${w.status==='pending'?'演示审核通过':offer?'下架':'查看作品'}</button></div></article>`;}).join(''):empty('第一件作品，会是什么样子？','上传你拥有版权的图片，选择所属城市，再为它起个名字。','create','','开始创作')}
 <div class="notice">${icon('shield')}<span>你保留作品版权。当前每次创作生成 1 份可寄送、可转售的数字使用权；不是 NFT，也不承诺保值。上架后不可同时寄出。未成交前收入为 0。</span></div>`;
}

function modal(title,html,wide=false,kind='generic',id=null){
 lastFocus=document.activeElement;activeModal={kind,id};document.body.style.overflow='hidden';
 $('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-head"><div><div class="eyebrow">POSTERPOSTA</div><h2 id="modal-title">${title}</h2></div><button class="icon-button" data-action="close" aria-label="关闭弹窗">${icon('close')}</button></header><div class="modal-body">${html}</div></section></div>`;
 setTimeout(()=>{const target=$('.modal input:not([type="checkbox"]):not([type="file"]):not(:disabled)') || $('.modal .icon-button');target?.focus({preventScroll:true});},60);
}
function closeModal(force=false){
 if(activeModal?.kind==='compose'&&!force){captureCompose();if(compose)storage.set('posterposta-draft',compose);toast('这封信已存为本地草稿，下次继续写');}
 $('#modal-root').innerHTML='';document.body.style.overflow='';activeModal=null;afterLogin=null;lastFocus?.focus?.({preventScroll:true});
}
function requireLogin(fn){if(PP.state.user){fn();return;}afterLogin=fn;loginModal();}
function loginModal(){const a=PP.state.account;modal(a?'欢迎回到小邮局':'用邮箱，开启你的旅程',`<div class="signin-art">${icon('mail')}<div><h3>A letter starts here.</h3><p>写给某个人，也写给未来的自己。</p></div></div><form id="login-form"><label class="field"><span class="field-label">你的昵称</span><input name="name" autocomplete="nickname" maxlength="50" value="${esc(a?.name||'') }" placeholder="怎么称呼你" required></label><label class="field"><span class="field-label">邮箱地址</span><input name="email" type="email" autocomplete="email" value="${esc(a?.email||'')}" placeholder="you@example.com" ${a?'readonly':''} required></label><label class="field"><span class="field-label">邮箱验证码<span>演示专用</span></span><div class="code-row"><input name="code" inputmode="numeric" autocomplete="one-time-code" maxlength="6" placeholder="输入 246810" required><button type="button" class="secondary" data-action="show-code">获取演示验证码</button></div></label><label class="check-row"><input type="checkbox" name="consent" required><span>我已了解这是本地交互演示，不会发送验证码或邮件。输入的数据仅保存在当前浏览器。</span></label><div id="form-error" class="inline-error" role="alert"></div><button class="primary full-width" type="submit">${a?'进入我的邮局':'注册并开启旅程'} ${icon('arrow')}</button><p class="auth-note">不用设置密码 · 演示验证码 246810<br>请使用测试邮箱，勿填写敏感信息。此处不具备真实账号认证能力。</p></form>`,false,'login');}
function locationModal(){modal('你在哪里，故事就从哪里开始。',`<p class="modal-intro">正式产品以服务端识别的当前 IP 城市提供当地作品，用户不能随意切城购买。这里的城市切换<strong>仅用于预览不同地点的体验</strong>，不是实际定位结果。</p><div class="notice">${icon('pin')}<span>当前为<strong>${city(PP.state.location).name}演示邮局</strong>。未调用定位服务，未读取或保存你的真实 IP 与坐标。</span></div><div class="city-options">${Object.entries(PP.cities).map(([id,c])=>`<button class="city-choice ${PP.state.location===id?'active':''}" data-action="set-location" data-id="${id}"><img src="${PP.product(id+'-free').img}" alt="${c.name}"><span><strong>${c.name}</strong><small>${c.en}</small></span>${PP.state.location===id?icon('check'):''}</button>`).join('')}</div><p class="layout-note">IP 定位失败或存在代理时，正式版应暂停当地购买并提供定位复核；已拥有的资产仍可使用，全球市集不受城市限制。</p>`,false,'location');}
function detail(productId,marketId){
 const p=PP.product(productId),m=marketId?PP.state.market.find(x=>x.id===marketId):null;const local=p.city===PP.state.location,free=p.price===0&&!m;
 const action=free?'claim':'checkout';
 modal('一小块风景，一段新故事。',`<div class="detail-layout"><div class="detail-image">${p.type==='stamp'?`<div class="stamp-large" style="width:185px;height:230px"><img src="${esc(p.img)}" alt="${esc(p.title)}" style="height:170px"><span>${city(p.city).en}<b>${fmt(p.price)}</b></span></div>`:`<img src="${esc(p.img)}" alt="${esc(p.title)}">`}</div><div class="detail-copy"><span class="status">${city(p.city).name} · ${m?'市集收藏':'当地限定'}</span><h3>${esc(p.title)}</h3><p class="detail-desc">${esc(m?.description||p.subtitle)}。${p.type==='card'?'为它写下一点想念，让这段风景与另一个人的生活相遇。':'每枚邮票都可以为一张明信片开启旅程。使用后会留在信件上，不再出现在未使用邮票册。'}</p><div class="detail-facts"><div><span>作品作者</span>${esc(p.creator)}</div><div><span>原始产地</span>${city(p.city).name} · ${city(p.city).country}</div><div><span>作品形式</span>${p.type==='card'?'数字明信片':'数字邮票'} · 1 份</div><div><span>获取方式</span>${m?'全球市集 · 不限位置':'当前城市邮局'}</div></div><div class="detail-price">${free?'免费':`¥${fmt(m?m.price:p.price)}`}<small>${free?'含一枚当地邮票':'仅数字使用权，非实物商品'}</small></div>${m?.own?`<button class="secondary" data-action="unlist" data-id="${m.id}">下架自己的作品</button>`:m&&!m.active?'<button class="primary" disabled>作品已成交或下架</button>':!m&&!local?`<button class="primary" data-action="nav" data-id="market">异地作品，请前往市集 ${icon('arrow')}</button>`:free&&PP.state.claimedFree?'<button class="primary" data-action="my-free">免费礼已领取 · 去我的收藏</button>':`<button class="primary" data-action="${action}" data-id="${p.id}" ${m?`data-market="${m.id}"`:''}>${free?'免费领取，写下此刻':`收藏这${p.type==='card'?'张明信片':'枚邮票'}`} ${icon('arrow')}</button>`}${m&&!m.own&&m.active?`<button class="secondary" data-action="consult" data-id="${m.id}">${icon('chat')} 和 ${esc(m.seller)} 聊一聊</button>`:''}<p class="tiny-note">演示购买，不扣款 · 已获得的作品可在「我的收藏」使用</p></div></div>`,true,'detail',p.id);
}
function checkout(productId,marketId,resume=false){requireLogin(()=>{
 const p=PP.product(productId),m=marketId?PP.state.market.find(x=>x.id===marketId):null,price=m?m.price:p.price;
 modal('把这份风景，放进你的收藏。',`<div class="checkout-summary"><img src="${esc(p.img)}" alt="${esc(p.title)}"><div><h3>${esc(p.title)}</h3><p>${city(p.city).name} · ${p.type==='card'?'数字明信片':'数字邮票'} · 1 份</p></div></div><div class="cost-row"><span>${m?'市集成交价':'作品价格'}</span><span>¥${fmt(price)}</span></div><div class="cost-row"><span>平台服务费</span><span>¥0 <small>· 演示免服务费</small></span></div><div class="cost-row total"><span>合计</span><strong>¥${fmt(price)}</strong></div><div class="notice">${icon('shield')}<span>当前为本地模拟订单，没有连接支付渠道，不会扣款。${m?'购买后此卖品下架，数字资产转入你的收藏。':'购买成功后，作品保存在你的收藏中。'}</span></div><div id="form-error" class="inline-error" role="alert"></div><div class="modal-actions"><button class="secondary" data-action="${resume?'resume-compose':'detail'}" data-id="${p.id}" ${m?`data-market="${m.id}"`:''}>返回</button><button class="primary" data-action="pay" data-id="${p.id}" ${m?`data-market="${m.id}"`:''} ${resume?'data-resume="true"':''}>确认演示购买 ${icon('check')}</button></div>`,false,'checkout');
 });}
function acquired(asset){const p=PP.product(asset.productId);render();modal('风景已收藏，想念可以出发。',`<div class="success-content"><div class="success-icon">${icon('check')}</div><h3>这份${city(p.city).name}，现在属于你。</h3><p>${esc(p.title)}已放入「我的收藏」。${asset.source==='free'?'<br>一枚当地邮票也已随卡附赠。':''}</p></div><div class="checkout-summary" style="margin-top:22px"><img src="${esc(p.img)}" alt="${esc(p.title)}"><div><h3>${esc(p.title)}</h3><p>未使用 · ${asset.source==='free'?'首次免费礼':'演示资产，无实际扣款'}</p></div></div><div class="modal-actions"><button class="secondary" data-action="nav" data-id="profile">放回收藏</button><button class="primary" data-action="${p.type==='card'?'compose':'choose-card'}" data-id="${asset.id}">${p.type==='card'?'现在写一张':'去挑一张卡片'} ${icon('pen')}</button></div>`,false,'acquired');}
function chooseCard(){requireLogin(()=>{const items=PP.ownAssets('unused').filter(a=>PP.product(a.productId).type==='card');modal('想用哪张风景，打开话匣子？',`<p class="modal-intro">从未使用的明信片中选择一张。寄出后，这份资产会随信交给收信人。</p><div class="postcard-grid" style="grid-template-columns:repeat(2,minmax(0,1fr))">${items.length?items.map(a=>cardTile(PP.product(a.productId),{asset:a})).join(''):empty('还没有未使用的明信片','先领取你的首张免费礼，或去邮局买一张。')}</div>`,false,'choose');});}
function startCompose(assetId){requireLogin(()=>{const a=PP.ownAssets('unused').find(a=>a.id===assetId);if(!a)throw new Error('这张明信片当前不可寄送，请从未使用收藏中重新选择。');const draft=storage.get('posterposta-draft',null);compose=draft?.assetId===assetId?draft:{assetId,stampAssetId:'',toName:'',toEmail:'',toCity:'',message:''};if(!PP.ownAssets('unused').some(a=>a.id===compose.stampAssetId)){compose.stampAssetId=PP.ownAssets('unused').find(a=>PP.product(a.productId).type==='stamp'&&PP.product(a.productId).city===PP.state.location)?.id || PP.ownAssets('unused').find(a=>PP.product(a.productId).type==='stamp')?.id || ''; }composeModal();});}
function captureCompose(){const f=$('#compose-form');if(!f||!compose)return;for(const key of ['toName','toEmail','toCity','message'])compose[key]=f.elements[key].value;}
function estimateHTML(){if(!compose?.toCity)return `${icon('clock')}<span>选择收信人的所在城市，估算这封信的旅行时间。邮箱地址无法推断地理位置。</span>`;const est=PP.deliveryEstimate(compose.toCity);return `${icon('clock')}<span>${city(PP.state.location).name} → ${city(compose.toCity).name}，约 ${fmt(est.distance)} km<br>预计 <strong>${est.min}–${est.max} 个工作日</strong>到达邮箱 · 不含周末</span>`;}
function composeModal(){
 if(!compose)return chooseCard();const a=PP.ownAssets().find(a=>a.id===compose.assetId),p=PP.product(a.productId),stamps=PP.ownAssets('unused').filter(a=>PP.product(a.productId).type==='stamp');
 modal('在风景背面，写一点想念。',`<div class="steps"><span class="step active"><b>1</b> 写寄语</span><span class="step-line"></span><span class="step"><b>2</b> 确认寄送</span><span class="step-line"></span><span class="step"><b>3</b> 等待抵达</span></div><div class="compose-layout"><div class="compose-left"><div class="postcard-preview"><img src="${esc(p.img)}" alt="${esc(p.title)}"><div class="preview-caption">${city(p.city).en}<small>WISH YOU WERE HERE</small></div></div><div class="postcard-back"><p class="back-to" id="live-to">TO ${esc(compose.toName||'那个想起的人')}</p><p id="live-message">${esc(compose.message||'把今天遇见的风景，写给你。')}</p><p class="back-sign">FROM ${esc(PP.state.user.name)}</p></div><div class="notice">${icon('pin')}<span>卡片产地：${city(p.city).name}<br>本次寄出邮戳：${city(PP.state.location).name}（演示定位）<br>市集购入的异地卡片和邮票，也可以从此刻所在城市寄出。</span></div></div><form id="compose-form"><div class="field-grid"><label class="field"><span class="field-label">收信人昵称</span><input name="toName" maxlength="50" placeholder="想寄给谁" value="${esc(compose.toName)}" required></label><label class="field"><span class="field-label">收信人所在城市</span>${citySelect('toCity',compose.toCity,true)}</label></div><label class="field"><span class="field-label">收信邮箱 <small>请仔细核对</small></span><input name="toEmail" type="email" placeholder="friend@example.com" value="${esc(compose.toEmail)}" required></label><label class="field"><span class="field-label">你的寄语 <small id="word-count">${compose.message.length} / 500</small></span><textarea name="message" maxlength="500" placeholder="今天发生了什么？或者，只说一句想你。" required>${esc(compose.message)}</textarea></label><div class="field-label">贴上一枚邮票 <small>每封信消耗 1 枚</small></div><div class="stamp-picker">${stamps.map(a=>`<button type="button" class="stamp-option ${a.id===compose.stampAssetId?'active':''}" data-action="select-stamp" data-id="${a.id}" aria-label="选择${esc(PP.product(a.productId).title)}">${stamp(PP.product(a.productId))}<small>${city(PP.product(a.productId).city).name} · 已拥有</small></button>`).join('')}<button type="button" class="stamp-option stamp-buy" data-action="buy-stamp">${icon('plus')}<small>选购当地邮票<br>¥${PP.product(PP.state.location+'-stamp').price} 起</small></button></div><div class="notice" id="delivery-estimate">${estimateHTML()}</div><div id="form-error" class="inline-error" role="alert"></div><div class="modal-actions"><button class="secondary" type="button" data-action="save-draft">保存草稿</button><button class="primary" type="submit">预览与确认 ${icon('arrow')}</button></div></form></div>`,true,'compose');
}
function confirmSend(){
 const a=PP.ownAssets().find(a=>a.id===compose.assetId),p=PP.product(a.productId),s=PP.ownAssets().find(a=>a.id===compose.stampAssetId);if(!s)throw new Error('请先选择一枚未使用的邮票。');const est=PP.deliveryEstimate(compose.toCity);
 if(compose.toEmail.trim().toLowerCase()===PP.state.user.email.toLowerCase())throw new Error('请填写朋友的邮箱，不能寄给自己。');
 storage.set('posterposta-draft',compose);
 modal('确认后，就让想念慢慢出发。',`<div class="steps"><span class="step"><b>✓</b> 写寄语</span><span class="step-line"></span><span class="step active"><b>2</b> 确认寄送</span><span class="step-line"></span><span class="step"><b>3</b> 等待抵达</span></div><div class="letter-message">${stamp(PP.product(s.productId))}${esc(compose.message)}<div class="letter-sign">${esc(PP.state.user.name)} · 寄自${city(PP.state.location).name}</div></div><div class="cost-row"><span>收信人</span><strong>${esc(compose.toName)}</strong></div><div class="cost-row"><span>收信邮箱</span><strong style="overflow-wrap:anywhere;text-align:right">${esc(compose.toEmail)}</strong></div><div class="cost-row"><span>旅行时间</span><span>${est.min}–${est.max} 个工作日 · ${city(compose.toCity).name}</span></div><div class="cost-row"><span>消耗资产</span><span>1 张明信片 + 1 枚邮票</span></div><div class="notice warm">${icon('info')}<span>请确认邮箱无误。模拟寄出后，本次明信片与邮票不再可转售或重复使用。正式版会进入延迟投递队列；本版仅保存本地记录，<strong>不会真的发邮件</strong>。</span></div><div id="form-error" class="inline-error" role="alert"></div><div class="modal-actions"><button class="secondary" data-action="resume-compose">再改一改</button><button class="primary" data-action="send-letter">模拟寄出明信片 ${icon('plane')}</button></div>`,false,'confirm-send');
}
function sendSuccess(l){render();modal('你的想念，已经启程。',`<div class="success-content"><div class="success-icon">${icon('plane')}</div><h3>下一站，${esc(l.toName)}的邮箱。</h3><p>有一份只属于你们的风景，正在慢慢靠近。</p></div><div class="route-ticket"><div class="route-city"><strong>${city(l.fromCity).name}</strong><small>${city(l.fromCity).en}</small></div><div class="route-middle">${icon('plane')}${l.days} 个工作日</div><div class="route-city"><strong>${city(l.toCity).name}</strong><small>${city(l.toCity).en}</small></div></div><div class="success-content"><p>预计 ${date(l.eta)} 抵达<br>${esc(l.toEmail)}</p></div><div class="notice">${icon('info')}<span>本次已创建本地演示信件，未发送真实邮件。可在信件详情中体验「投递完成」与聊天解锁。</span></div><div class="modal-actions"><button class="secondary" data-action="nav" data-id="postoffice">再看看风景</button><button class="primary" data-action="letter" data-id="${l.id}">查看这封信 ${icon('arrow')}</button></div>`,false,'success');}
function chatMessages(list){return `<div class="chat-messages">${list.map(m=>`<div class="chat-bubble ${m.author==='我'?'me':''}"><small>${esc(m.author)} · ${date(m.time)}</small><p>${esc(m.text)}</p></div>`).join('')}</div>`;}
function letterModal(id){
 const l=PP.state.letters.find(x=>x.id===id);if(!l)throw new Error('信件暂时找不到了');const p=PP.product(l.productId),locked=l.status==='transit';
 modal('把故事，留在这张明信片下面。',`<div class="postcard-preview" style="aspect-ratio:1.9;max-height:260px;transform:none"><img src="${esc(p.img)}" alt="${esc(p.title)}"><div class="preview-caption">${city(p.city).en}<small>${esc(p.title)}</small></div></div><div class="letter-meta"><span>${city(l.fromCity).name} · ${esc(l.fromName)} → ${esc(l.toName)}</span>${badge(l.status)}</div><div class="letter-message">${stamp(PP.product(l.stampId))}${esc(l.message)}<div class="letter-sign">${date(l.sentAt)} · 寄自${city(l.fromCity).name}</div></div>${locked?`<div class="notice">${icon('clock')}<span>预计 ${date(l.eta)} 抵达 · ${l.days} 个工作日<br>目的地：${city(l.toCity).name} · ${esc(l.toEmail)}</span></div>`:''}<div class="chat-heading"><strong>明信片下的对话</strong><small>只属于你们 · 本地演示</small></div>${locked?`<div class="locked-chat">${icon('lock')}朋友收到信后，这里的对话才会开启。<button class="text-link" data-action="deliver" data-id="${l.id}">体验投递完成，解锁聊天 ↗</button></div>`:`${chatMessages(l.messages)}<form class="chat-form" id="letter-reply-form" data-id="${l.id}"><input name="text" aria-label="写一封回信" placeholder="继续聊聊这张明信片…" maxlength="500" required><button type="submit" class="primary" aria-label="发送回复">${icon('arrow')}</button></form>`}<div id="form-error" class="inline-error" role="alert"></div><div class="modal-actions"><button class="secondary" data-action="email-preview" data-id="${l.id}">${icon('mail')} 查看收信邮件样式</button><button class="secondary" data-action="report" data-id="${l.id}">${icon('flag')} 举报 / 隐私</button></div><p class="auth-note">此页面不会向任何邮箱发送信息，聊天仅保存在当前浏览器。</p>`,false,'letter',id);
}
function threadModal(id){const t=PP.state.community.find(x=>x.id===id);if(!t)throw new Error('话题暂时找不到了');const p=PP.product(t.productId);modal(`与 ${esc(t.peer)} 聊聊这份风景`, `<div class="checkout-summary"><img src="${esc(p.img)}" alt="${esc(p.title)}"><div><h3>${esc(p.title)}</h3><p>${esc(t.title)}</p></div></div>${chatMessages(t.messages)}<form class="chat-form" id="thread-reply-form" data-id="${id}"><input name="text" aria-label="市集交流内容" placeholder="关于这份风景，你想说…" maxlength="500" required><button type="submit" class="primary">${icon('arrow')}</button></form><div id="form-error" class="inline-error" role="alert"></div><p class="auth-note">市集交流会保存在「来往信件 → 市集交流」。当前没有真实卖家在线回复。</p><button class="tip-button" data-action="report" data-id="${id}">${icon('flag')} 举报不当内容 / 隐私说明</button>`,false,'thread',id);}
function consult(id){requireLogin(()=>{const m=PP.state.market.find(x=>x.id===id),p=PP.product(m.productId),t=PP.state.community.find(t=>t.marketId===id);if(t)return threadModal(t.id);modal(`向 ${esc(m.seller)} 说声你好`, `<div class="checkout-summary"><img src="${esc(p.img)}" alt="${esc(p.title)}"><div><h3>${esc(p.title)}</h3><p>${city(p.city).name} · ¥${fmt(m.price)}</p></div></div><form id="consult-form" data-id="${id}"><label class="field"><span class="field-label">关于这份风景，你想聊什么？</span><textarea name="message" maxlength="500" required placeholder="你好，这张明信片背后有什么故事吗？"></textarea></label><p class="field-hint">咨询会沉淀到「来往信件 → 市集交流」。当前仅本地保存，不会实际通知卖家。</p><div id="form-error" class="inline-error" role="alert"></div><div class="modal-actions"><button type="submit" class="primary">开始这段交流 ${icon('chat')}</button></div></form>`,false,'consult');});}
function assetDetail(id){const a=PP.ownAssets().find(a=>a.id===id);if(!a)throw new Error('未找到此资产');const p=PP.product(a.productId);if(a.status==='received'||a.status==='sent'){const l=PP.state.letters.find(l=>l.assetId===id);if(l)return letterModal(l.id);}if(a.status==='unused'&&p.type==='card'){return startCompose(id);}modal('你的私人珍藏',`<div class="checkout-summary"><img src="${esc(p.img)}" alt="${esc(p.title)}"><div><h3>${esc(p.title)}</h3><p>${city(p.city).name} · ${statusText[a.status]}</p></div></div><p class="modal-intro">${p.type==='stamp'?'邮票会随信寄出，一枚只能使用一次。邮票原始产地不会因寄送城市而改变。':'已上架作品暂时锁定，先下架，才能写信或再次转售。'}</p><div class="notice">${icon('info')}<span>来源：${({free:'首张免费礼',gift:'免费附赠',shop:'当地邮局',market:'全球市集',sample:'演示示例',creation:'原创作品'})[a.source]||'收藏'}<br>数字资产编号：${esc(a.id)}</span></div><div class="modal-actions">${a.status==='unused'?`<button class="secondary" data-action="list-asset" data-id="${a.id}">转售到市集</button><button class="primary" data-action="choose-card">挑张卡片开始写 ${icon('pen')}</button>`:a.status==='listed'?`<button class="primary" data-action="unlist" data-id="${PP.state.market.find(m=>m.assetId===id&&m.active)?.id||''}">下架并放回收藏</button>`:'<button class="secondary" data-action="close">知道了</button>'}</div>`,false,'asset');}
function listAssetModal(id){requireLogin(()=>{const a=PP.ownAssets().find(a=>a.id===id),p=PP.product(a.productId);if(a.source==='free'||a.source==='gift'||p.price===0)throw new Error('免费明信片与赠送邮票不支持转售，留给一封特别的信吧。');const creation=PP.state.creations.find(w=>w.productId===p.id);if(creation?.status==='pending')throw new Error('请先在创作中心完成演示审核，再上架作品。');modal('给这份风景，找一个新主人。',`<div class="checkout-summary"><img src="${esc(p.img)}" alt="${esc(p.title)}"><div><h3>${esc(p.title)}</h3><p>${city(p.city).name} · 未使用 · 1 份</p></div></div><form id="list-form" data-id="${id}"><label class="field"><span class="field-label">你的定价（元）</span><input type="number" name="price" min="0.01" max="999" step="0.01" required value="${p.price}"></label><label class="field"><span class="field-label">说说它的故事</span><textarea name="description" maxlength="500" placeholder="它在哪里遇见你，又为什么想让它继续旅行？"></textarea></label><div class="notice">${icon('lock')}<span>上架后这份资产将锁定，不能同时寄出。下架后恢复使用。全球旅行者均可购买；本次仅上架到本地演示市集。</span></div><div id="form-error" class="inline-error" role="alert"></div><button type="submit" class="primary full-width">确认上架 ${icon('arrow')}</button></form>`,false,'list');});}
function createModal(){requireLogin(()=>{creationImage='';modal('给一座城市，做一张自己的名片。',`<p class="modal-intro">照片、画作、手绘都可以。作品可以属于世界上的另一座城市，不必是你当前所在地。</p><form id="creation-form"><label class="upload-zone" id="upload-zone"><div id="upload-preview" style="text-align:center">${icon('upload')}<p>放进一张你创作的图片</p><small>点击选择 · JPG / PNG / WebP · 最大 2 MB</small></div><input type="file" id="art-upload" accept="image/png,image/jpeg,image/webp" aria-label="上传原创作品"></label><p class="field-hint">建议横版 3:2 明信片、竖版 3:4 邮票；预览会居中裁切，原图保留。</p><div class="field-grid" style="margin-top:19px"><label class="field"><span class="field-label">作品类型</span><select name="type"><option value="card">明信片</option><option value="stamp">邮票</option></select></label><label class="field"><span class="field-label">绑定城市</span>${citySelect('city',PP.state.location)}</label></div><label class="field"><span class="field-label">作品名字 <small>2–30 字</small></span><input name="title" minlength="2" maxlength="30" placeholder="例如：巴黎的某个晴天下午" required></label><div class="field-grid"><label class="field"><span class="field-label">定价（元）</span><input name="price" type="number" min="0.01" max="999" step="0.01" value="12" required></label><label class="field"><span class="field-label">发行份数</span><input value="1 份数字使用权" readonly></label></div><label class="field"><span class="field-label">创作故事</span><textarea name="description" maxlength="500" placeholder="为什么想把这幅风景留下来？"></textarea></label><label class="check-row"><input type="checkbox" name="rights" required><span>我拥有这张图片的版权或已获得授权，并同意在通过审核后公开展示。内容不含他人隐私、侵权素材或违法信息。</span></label><div class="notice">${icon('shield')}<span>提交后，你将拥有这件原创资产。审核前不进入市集；可在创作中心体验演示审核。上架将锁定这一份资产，版权不转移。</span></div><div id="form-error" class="inline-error" role="alert"></div><button type="submit" class="primary full-width">保存作品，提交演示审核 ${icon('arrow')}</button></form>`,false,'create');});}
function emailPreview(id){const l=PP.state.letters.find(x=>x.id===id),p=PP.product(l.productId);modal('收信人会遇见怎样的一封邮件？',`<div class="mail-preview"><div class="mail-toolbar">收件人：${esc(l.toEmail)}<br>主题：${esc(l.fromName)} 从${city(l.fromCity).name}寄来了一张明信片</div><div class="mail-content"><div class="brand">PosterPosta<span class="brand-dot">.</span></div><img src="${esc(p.img)}" alt="${esc(p.title)}"><h3>${esc(l.toName)}，有一份风景想见你。</h3><p>${esc(l.fromName)}把${city(l.fromCity).name}的一点想念，<br>放进了你的邮箱。</p><button class="primary full-width" data-action="recipient-preview" data-id="${id}">打开这张明信片 ${icon('arrow')}</button><p class="auth-note">无需安装 App 即可查看；验证收信邮箱后，才能签收并回信。<br>正式邮件需提供「拒收此发件人 / 退订」链接。</p></div></div><p class="auth-note">这是邮件样式预览，并非已发送邮件。此按钮只打开本地收信视角。</p>`,false,'email');}
function recipientPreview(id){const l=PP.state.letters.find(x=>x.id===id);modal('收信视角 · 仅供体验',`<div class="success-content"><div class="success-icon">${icon('mail')}</div><h3>亲爱的 ${esc(l.toName)}，见字如面。</h3><p>以下为收信页样式，未登录真实收信人账号。</p></div><div class="letter-message" style="margin-top:22px">${esc(l.message)}<div class="letter-sign">${esc(l.fromName)} · ${city(l.fromCity).name}</div></div><div class="notice">${icon('lock')}<span>正式产品将通过邮件中的一次性签名链接打开只读信件。签收、领取资产和回复前，必须验证 ${esc(l.toEmail)} 的所有权，不会把信件分配给当前发送者。</span></div><button class="secondary full-width" data-action="letter" data-id="${id}">返回发送者的信件详情</button>`,false,'recipient');}
const rules=[
 ['位置，让记忆有出处','当地邮局只允许获取当前 IP 识别城市的作品；首张免费在前，其余为当地付费收藏。市集购入的异地作品可以持有、寄出和再次转售。卡片产地永久保留，寄出邮戳记录实际寄信城市，二者不混淆。'],
 ['第一张，真的不用付费','每个账号跨城市共 1 次免费名额，并附赠 1 枚同城邮票。免费卡片和赠送邮票不可转售，以避免套利。之后购买的每份资产独立计数，喜欢列表不等于已拥有。'],
 ['一份资产，只踏上一段旅程','一封数字邮件消耗 1 张未使用明信片和 1 枚未使用邮票。上架、寄出、已使用、已签收的资产不能重复寄出。已签收明信片作为私人纪念收藏，不参与公开转售。上架锁定资产，下架恢复。'],
 ['让等待成为体验，而不是黑箱','用发信与收信城市的粗略距离估算：≤1000 km 为 1–3 个工作日，1000–5000 km 为 3–6 日，超过 5000 km 为 6–10 日。随机值在提交时确定一次，排除周末，不精算各国节假日。邮箱本身不能推断位置，收信城市由寄件人提供。'],
 ['投递、签收，不是同一回事','寄送中只能看，不能聊；邮件成功投递后可开启对话，收信人验证邮箱并接受后记为已签收。正式版需以邮件服务回执和一次性签名链接确认，不把点击预览视为真实送达。收件方未注册也可先读信，认证后领取与回复。'],
 ['创作可以自由，版权不能随意','可将原创明信片或邮票绑定任意城市，上传后先审核再公开。你保留版权；买家获得约定份数的数字使用权，而非版权或实物。此版本每次创作 1 份，更多发行机制须独立定义。'],
 ['交易有边界，隐私有底线','仅未使用的资产可交易。正式版需服务端原子锁定、幂等支付、退款与争议处理；拒付、退信或不可投递应进入人工支持。邮箱只用于身份与投递，不能被市集买家看到。聊天需举报、拉黑和拒收入口，创作需内容审核。'],
 ['当前，你在一间演示邮局里','注册、IP 城市、支付、物流、聊天与审核均为本地模拟。演示验证码为 246810；不会发送邮件、扣款、公开上传或通知他人。刷新可继续当前旅程；清除本地数据后不可恢复。不能作为真实账号、真实位置或真实交易凭据。']
];
function rulesModal(){modal('邮局公约 · 小事也要认真',`<div class="rules-list">${rules.map(([t,p])=>`<section class="rule-item"><h3>${t}</h3><p>${p}</p></section>`).join('')}</div><button class="primary full-width" data-action="close">知道了，继续旅程 ${icon('check')}</button>`,false,'rules');}
function demoModal(){modal('一间可体验，尚未联网营业的邮局。',`<p class="modal-intro">本版可以完整走通注册、领取、写信、贴邮票、模拟寄出、解锁聊天、市集交易、创作审核和收藏管理。操作会保存在当前浏览器。</p><div class="rules-list"><section class="rule-item"><h3>已经可以体验</h3><p>六座演示城市、跨城市市集、免费名额、资产锁定与消耗、工作日投递估算、草稿恢复、邮件收信样式、双消息列表、创作中心、收入与订单记录。</p></section><section class="rule-item"><h3>上线前必须接入</h3><p>服务端邮箱认证与数据库、合规 IP 定位库、真实支付与退款、邮件延迟队列与幂等重试、送达/退信回执、聊天服务、对象存储、人工内容审核与申诉。服务端应校验每次获取资格，不能依赖前端切城或本地状态防套利。</p></section><section class="rule-item"><h3>你输入的信息</h3><p>只存本地，不上传。请使用测试邮箱和可公开测试图片。此页面里的图片是旅行摄影示意素材，不代表线上可销售的授权素材库。</p></section></div><div class="modal-actions"><button class="secondary" data-action="location">体验另一座城市</button><button class="primary" data-action="close">继续逛逛 ${icon('arrow')}</button></div>`,false,'demo');}
function settingsModal(){modal('照顾好你的私人邮局。',`<div class="settings-menu"><button data-action="${PP.state.user?'account-info':'login'}">${icon('mail')}<span>邮箱账号</span><span>${PP.state.user?esc(PP.state.user.email):'未登录'} ›</span></button><button data-action="transactions">${icon('wallet')}<span>订单与收支</span><span>›</span></button><button data-action="rules">${icon('shield')}<span>隐私、资产与邮局公约</span><span>›</span></button><button data-action="demo">${icon('info')}<span>体验版说明 / 上线边界</span><span>›</span></button>${PP.state.user?`<button data-action="logout">${icon('logout')}<span>退出演示账号</span><span>保留本地资产 ›</span></button>`:''}<button data-action="reset-confirm">${icon('settings')}<span>重新开始体验</span><span>重置本地演示 ›</span></button></div>`,false,'settings');}
function transactionsModal(){const ts=PP.state.transactions.slice().reverse();modal('每一份风景，都有一张收据。',`<p class="modal-intro">仅记录演示订单，不代表实际付款或收入。未成交的原创作品不产生收入。</p>${ts.length?ts.map(t=>`<div class="transaction"><div><h3>${esc(PP.product(t.productId).title)}</h3><p>${esc(t.description)} · ${date(t.createdAt)}</p></div><strong>${t.amount<0?'−':''}¥${fmt(Math.abs(t.amount))}</strong></div>`).join(''):empty('还没有收据','领取第一份风景，开启你的旅程。')}<div class="notice">${icon('wallet')}<span>真实支付与提现尚未接入，当前可结算收入为 ¥${fmt(PP.state.revenue)}。这里不会模拟提现成功。</span></div>`,false,'transactions');}
function reportModal(id){modal('每一份来往，都应当被尊重。',`<form id="report-form" data-id="${esc(id)}"><label class="field"><span class="field-label">遇到什么问题？</span><select name="reason"><option>骚扰或不友善内容</option><option>涉嫌侵权</option><option>交易纠纷</option><option>隐私泄露</option><option>不再接收此类内容</option></select></label><label class="field"><span class="field-label">补充说明（选填）</span><textarea name="message" maxlength="500" placeholder="请勿在此填写身份证、银行卡等敏感信息。"></textarea></label><div class="notice">${icon('shield')}<span>本版仅保存一条本地反馈，不会发送给客服。正式版需接入举报工单、发件人屏蔽、处理结果通知与拒收名单。</span></div><div id="form-error" class="inline-error" role="alert"></div><button class="primary full-width" type="submit">保存本地反馈</button></form>`,false,'report');}

async function action(el){
 const a=el.dataset.action,id=el.dataset.id,m=el.dataset.market;
 if(a==='nav')return navigate(id);
 if(a==='close')return closeModal();
 if(a==='filter'){filter=id;render();if(id==='stamps')$('.section-heading')?.scrollIntoView({block:'start',behavior:'smooth'});return;}
 if(a==='favorite'){favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];storage.set('posterposta-favorites',favorites);render();return toast(favorites.includes(id)?'已喜欢，可在「我的收藏 → 我喜欢的」找到':'已取消喜欢');}
 if(a==='market-type'){marketType=id;return render();}
 if(a==='clear-market'){marketType='all';marketCity='all';marketSearch='';marketSort='new';return render();}
 if(a==='message-tab'){messageTab=id;return render();}
 if(a==='profile-type'){profileType=id;return render();}
 if(a==='asset-tab'){assetTab=id;return render();}
 if(a==='location')return locationModal();
 if(a==='set-location'){if(compose)captureCompose();PP.setLocation(id);filter='all';closeModal(true);render();return toast(`已切换到${city(id).name}演示邮局，不代表真实定位`);}
 if(a==='account')return PP.state.user?settingsModal():loginModal();
 if(a==='login')return loginModal();
 if(a==='show-code'){const input=$('input[name="code"]');if(input)input.value='246810';return toast('演示验证码为 246810，没有发送邮件');}
 if(a==='detail')return detail(id,m);
 if(a==='claim')return requireLogin(()=>{const asset=PP.acquire(id);acquired(asset);});
 if(a==='checkout')return checkout(id,m);
 if(a==='pay'){el.disabled=true;el.classList.add('button-loading');try{const asset=PP.acquire(id,m);if(el.dataset.resume&&compose){compose.stampAssetId=asset.id;render();composeModal();toast('邮票已放进收藏，继续写信吧');}else acquired(asset);}catch(e){el.disabled=false;el.classList.remove('button-loading');throw e;}return;}
 if(a==='my-free'){return requireLogin(()=>{const free=PP.ownAssets('unused').find(a=>a.source==='free'&&PP.product(a.productId).type==='card');if(free)startCompose(free.id);else chooseCard();});}
 if(a==='compose')return startCompose(id);
 if(a==='choose-card'||a==='use-stamp')return chooseCard();
 if(a==='select-stamp'){captureCompose();compose.stampAssetId=id;return composeModal();}
 if(a==='buy-stamp'){captureCompose();storage.set('posterposta-draft',compose);return modal('为这封信，挑一枚当地邮票。',`<p class="modal-intro">来自${city(PP.state.location).name}的特色邮票。购买后自动贴上这封信，已经写好的寄语不会丢失。</p><div class="postcard-grid" style="grid-template-columns:repeat(2,minmax(0,1fr))">${PP.cityProducts('stamp').map(p=>`<article class="postcard stamp-product"><button class="postcard-art" data-action="checkout-stamp" data-id="${p.id}" aria-label="购买${esc(p.title)}"><div class="stamp-large"><img src="${esc(p.img)}" alt="${esc(p.title)}"><span>${city(p.city).en}<b>${p.price}</b></span></div></button><div class="card-info"><h3>${esc(p.title)}</h3><span class="card-price">¥${p.price}</span></div></article>`).join('')}</div><div class="modal-actions"><button class="secondary" data-action="resume-compose">返回信件</button></div>`,false,'buy-stamp');}
 if(a==='checkout-stamp')return checkout(id,null,true);
 if(a==='save-draft'){captureCompose();storage.set('posterposta-draft',compose);closeModal(true);return toast('草稿已保存，打开这张卡片即可继续写');}
 if(a==='resume-compose')return composeModal();
 if(a==='send-letter'){el.disabled=true;try{const l=PP.sendLetter(compose);compose=null;storage.set('posterposta-draft',null);return sendSuccess(l);}catch(e){el.disabled=false;throw e;}}
 if(a==='letter')return letterModal(id);
 if(a==='deliver')return requireLogin(()=>{PP.markDelivered(id);render();letterModal(id);toast('已模拟投递完成，聊天开启；未发送真实邮件');});
 if(a==='thread')return threadModal(id);
 if(a==='consult')return consult(id);
 if(a==='asset-detail')return assetDetail(id);
 if(a==='list-asset')return listAssetModal(id);
 if(a==='unlist')return requireLogin(()=>{PP.unlistAsset(id);closeModal(true);render();toast('已下架，资产回到未使用收藏');});
 if(a==='create')return createModal();
 if(a==='review'){return requireLogin(()=>{PP.reviewCreation(id);render();toast('演示审核已通过，作品已上架本地市集');});}
 if(a==='email-preview')return emailPreview(id);
 if(a==='recipient-preview')return recipientPreview(id);
 if(a==='rules'||a==='creator-rules')return rulesModal();
 if(a==='how')return modal('把此刻，寄给远方。',`<div class="rules-list"><section class="rule-item"><h3>在你所在的城市，发现一张卡片</h3><p>第一张免费，连邮票也为你准备好了。每一座城市都有自己的风景，离开后，就只能在世界市集里再次遇见。</p></section><section class="rule-item"><h3>写下此刻，给那个想起的人</h3><p>选枚邮票，填入朋友的邮箱与所在城市。无需知道街道地址，就能寄去一份数字想念。</p></section><section class="rule-item"><h3>等一等，让距离有一点浪漫</h3><p>1–10 个工作日后，信件抵达。朋友验证邮箱后可以签收、回复，让一张明信片成为属于你们的聊天起点。</p></section></div><button class="primary full-width" data-action="close">去发现我的第一张 ${icon('arrow')}</button>`,false,'how');
 if(a==='demo')return demoModal();
 if(a==='settings')return settingsModal();
 if(a==='transactions')return transactionsModal();
 if(a==='account-info')return modal('你的邮箱账号',`<div class="notice">${icon('mail')}<span>${esc(PP.state.user.name)}<br>${esc(PP.state.user.email)}<br>本地演示账号 · 未真实验证邮箱所有权</span></div><p class="modal-intro">为避免把既有收藏换绑给另一个邮箱，此浏览器内不能直接更换账号。退出后可用同一邮箱与演示验证码重新进入。</p><button class="secondary full-width" data-action="settings">返回设置</button>`);
 if(a==='logout'){PP.logout();closeModal(true);render();return toast('已退出，收藏与信件保留在当前浏览器');}
 if(a==='reset-confirm')return modal('重新开始，会清空这段演示旅程。',`<p class="modal-intro">将删除此应用在当前浏览器保存的账号、草稿、收藏、信件、咨询、订单、上传作品与喜欢记录，并恢复初始示例。</p><div class="notice warm">${icon('info')}<span>此操作不可撤销。不会操作你的电脑文件，也不会影响真实邮箱或支付账户。</span></div><div class="modal-actions"><button class="secondary" data-action="settings">保留我的旅程</button><button class="danger-btn" data-action="reset">确认清空本地演示</button></div>`);
 if(a==='reset'){PP.reset();for(const k of ['posterposta-draft','posterposta-favorites','posterposta-reports'])localStorage.removeItem(k);favorites=[];compose=null;filter='all';navigate('postoffice');return toast('演示已重新开始，欢迎回到小邮局');}
 if(a==='report')return reportModal(id);
}

document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el&&!el.disabled){e.preventDefault();Promise.resolve(action(el)).catch(error);}else if(e.target.classList.contains('modal-backdrop'))closeModal();});
document.addEventListener('submit',e=>{
 e.preventDefault();const f=e.target;const data=new FormData(f);const d=Object.fromEntries(data);try{
 if(f.id==='login-form'){if(!data.has('consent'))throw new Error('请先阅读并确认演示说明');PP.register(d.email,d.name,d.code);const next=afterLogin;afterLogin=null;closeModal(true);render();toast('欢迎来到 PosterPosta，你的小邮局已开启');if(next)next();}
 else if(f.id==='compose-form'){captureCompose();if(!compose.message.trim())throw new Error('先写一点想念吧');if(!compose.stampAssetId)throw new Error('请贴上一枚邮票');confirmSend();}
 else if(f.id==='letter-reply-form'){const id=f.dataset.id,text=d.text;requireLogin(()=>{PP.reply(id,text);render();letterModal(id);toast('回复已本地保存');});}
 else if(f.id==='thread-reply-form'){const id=f.dataset.id,text=d.text;requireLogin(()=>{PP.comment(id,text);render();threadModal(id);toast('消息已本地保存');});}
 else if(f.id==='consult-form'){const thread=PP.startThread(f.dataset.id,d.message);render();threadModal(thread.id);toast('交流已收进市集消息');}
 else if(f.id==='list-form'){PP.listAsset(f.dataset.id,Number(d.price),d.description);closeModal(true);render();toast('已上架到世界市集，资产暂时锁定');}
 else if(f.id==='creation-form'){if(!creationImage)throw new Error('请先上传一张原创图片');PP.createWork({...d,price:Number(d.price),img:creationImage,rights:data.has('rights')});closeModal(true);navigate('creator');toast('作品已保存并拥有，请在创作中心完成演示审核');}
 else if(f.id==='report-form'){const list=storage.get('posterposta-reports',[]);list.push({target:f.dataset.id,reason:d.reason,message:d.message,createdAt:new Date().toISOString()});storage.set('posterposta-reports',list);closeModal(true);toast('反馈已保存在本地，尚未提交给客服');}
 }catch(e){error(e);}
});
let searchTimer;
document.addEventListener('input',e=>{
 if(e.target.id==='market-search'){marketSearch=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const start=e.target.selectionStart;render();const inp=$('#market-search');inp?.focus();inp?.setSelectionRange(start,start);},300);}
 if(e.target.closest('#compose-form')){captureCompose();if($('#live-message'))$('#live-message').textContent=compose.message||'把今天遇见的风景，写给你。';if($('#live-to'))$('#live-to').textContent='TO '+(compose.toName||'那个想起的人');$('#word-count').textContent=compose.message.length+' / 500';storage.set('posterposta-draft',compose);}
});
document.addEventListener('change',async e=>{try{
 if(e.target.id==='market-city'){marketCity=e.target.value;render();}
 if(e.target.id==='market-sort'){marketSort=e.target.value;render();}
 if(e.target.id==='toCity'){captureCompose();$('#delivery-estimate').innerHTML=estimateHTML();}
 if(e.target.id==='art-upload'){
  const file=e.target.files[0];if(!file)return;
  if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('请选择 JPG、PNG 或 WebP 图片，不支持 SVG');
  if(file.size>2*1024*1024)throw new Error('图片需小于 2 MB，请压缩后再上传');
  const result=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(new Error('图片读取失败'));r.readAsDataURL(file);});
  await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve();img.onerror=()=>reject(new Error('这份文件无法解码为图片'));img.src=result;});
  if(activeModal?.kind!=='create')return;creationImage=result;$('#upload-preview').innerHTML=`<img src="${esc(result)}" alt="你的原创作品预览">`;$('#upload-preview').style.width='100%';
 }
 }catch(err){creationImage='';error(err);}
});
document.addEventListener('keydown',e=>{
 if(e.key==='Escape'&&activeModal){e.preventDefault();closeModal();}
 if(e.key==='Tab'&&activeModal){const els=[...document.querySelectorAll('.modal button:not(:disabled),.modal input:not(:disabled),.modal select,.modal textarea,.modal a')].filter(el=>el.offsetParent!==null);const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}
});
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(['postoffice','messages','market','profile','creator'].includes(v)){view=v;closeModal(true);render();}});
window.addEventListener('beforeunload',()=>{if(compose){captureCompose();storage.set('posterposta-draft',compose);}});
render();
})();
